import{_ as a,o as t,c as i,a5 as r}from"./chunks/framework.BF53ZjCA.js";const m=JSON.parse('{"title":"Silicates — Chain / Band (Inosilicates)","description":"","frontmatter":{"title":"Silicates — Chain / Band (Inosilicates)","mineralGroup":"silicates-chain"},"headers":[],"relativePath":"classification/mineral-groups/silicates-chain.md","filePath":"classification/mineral-groups/silicates-chain.md","lastUpdated":1790876393000}'),s={name:"classification/mineral-groups/silicates-chain.md"};function n(l,e,o,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="silicates-—-chain-band-inosilicates" tabindex="-1">Silicates — Chain / Band (Inosilicates) <a class="header-anchor" href="#silicates-—-chain-band-inosilicates" aria-label="Permalink to &quot;Silicates — Chain / Band (Inosilicates)&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Chain silicates encompass two major gem-bearing families:</p><ul><li><strong>Pyroxenes (single chain)</strong>: jadeite, diopside, spodumene (kunzite, hiddenite)</li><li><strong>Amphiboles (double chain)</strong>: nephrite, actinolite, tremolite &quot;Jade&quot; includes both jadeite (a pyroxene) and nephrite (an amphibole) — chemically and structurally distinct despite shared cultural identity.</li></ul><h2 id="formula-class" tabindex="-1">Formula Class <a class="header-anchor" href="#formula-class" aria-label="Permalink to &quot;Formula Class&quot;">​</a></h2><p>M·SiO₃ / M₇Si₈O₂₂(OH)₂</p><h2 id="crystal-structure" tabindex="-1">Crystal Structure <a class="header-anchor" href="#crystal-structure" aria-label="Permalink to &quot;Crystal Structure&quot;">​</a></h2><p>[SiO₄] tetrahedra share two oxygens to form single chains (pyroxenes) or 2:1 double chains (amphiboles). Chains are bridged by metal cations (Ca, Mg, Fe) and OH⁻ groups. Chain structure running along the c-axis produces characteristic prismatic or fibrous crystal habits.</p><h2 id="representative-gem-species" tabindex="-1">Representative Gem Species <a class="header-anchor" href="#representative-gem-species" aria-label="Permalink to &quot;Representative Gem Species&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Formula</th><th>Subgroup</th></tr></thead><tbody><tr><td>Jadeite (Burmese Jade) / 翡翠</td><td>NaAlSi₂O₆</td><td>pyroxene</td></tr><tr><td>Nephrite / 软玉</td><td>Ca₂(Mg,Fe)₅Si₈O₂₂(OH)₂</td><td>amphibole</td></tr><tr><td>Spodumene (Kunzite) / 孔赛石</td><td>LiAlSi₂O₆</td><td>pyroxene</td></tr><tr><td>Spodumene (Hiddenite) / 翠绿锂辉石</td><td>LiAlSi₂O₆ + Cr</td><td>pyroxene</td></tr><tr><td>Diopside / 透辉石</td><td>CaMgSi₂O₆</td><td>pyroxene</td></tr><tr><td>Rhodonite / 蔷薇辉石</td><td>MnSiO₃</td><td>pyroxenoid</td></tr><tr><td>Actinolite / 阳起石</td><td>Ca₂(Mg,Fe)₅Si₈O₂₂(OH)₂</td><td>amphibole</td></tr></tbody></table><p><em>See the <a href="./intro.html">mineral group overview</a>.</em></p><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://elearning-samples.gia.edu/Gem_Identification/Page5.html" target="_blank" rel="noreferrer">GIA: Gem Species, Varieties, and Groups</a><span>Relationships among mineral species, gem varieties, and mineral groups</span><small>Open source ↗</small></li><li><a href="https://www.mindat.org/" target="_blank" rel="noreferrer">Mindat mineral database</a><span>Mineral names, chemistry, and classification lookup</span><small>Open source ↗</small></li></ul></aside>',12)])])}const u=a(s,[["render",n]]);export{m as __pageData,u as default};
